from fractions import Fraction
import re
import ast

def fraction_expr(s: str) -> str:
    if not isinstance(s, str) or not s.strip():
        raise ValueError("empty input")

    # Validate tokens
    token_pattern = re.compile(r'\s*(\d+/\d+|\d+|[()+\-*])')
    pos = 0
    tokens = []
    n = len(s)
    while pos < n:
        if s[pos].isspace():
            pos += 1
            continue
        m = token_pattern.match(s, pos)
        if not m:
            raise ValueError("malformed input")
        tok = m.group(1)
        tokens.append(tok)
        pos = m.end()

    if not tokens:
        raise ValueError("empty input")

    # Convert fraction tokens to a safe python expression using Fraction()
    def tok_to_pyexpr(tok):
        if re.fullmatch(r'\d+/\d+', tok):
            num, den = tok.split('/')
            den_i = int(den)
            if den_i == 0:
                raise ValueError("zero denominator")
            return f"Fraction({num},{den})"
        elif re.fullmatch(r'\d+', tok):
            return f"Fraction({tok})"
        else:
            return tok

    py_tokens = [tok_to_pyexpr(t) for t in tokens]
    expr_str = ' '.join(py_tokens)

    # Parse with ast to validate structure safely, allowing only limited node types
    try:
        node = ast.parse(expr_str, mode='eval')
    except SyntaxError:
        raise ValueError("malformed input")

    allowed_nodes = (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Add, ast.Sub,
                      ast.Mult, ast.USub, ast.UAdd, ast.Call, ast.Name, ast.Load,
                      ast.Constant)

    def check_node(nd):
        if not isinstance(nd, allowed_nodes):
            raise ValueError("malformed input")
        if isinstance(nd, ast.Call):
            if not (isinstance(nd.func, ast.Name) and nd.func.id == 'Fraction'):
                raise ValueError("malformed input")
            for arg in nd.args:
                if not isinstance(arg, ast.Constant) or not isinstance(arg.value, int):
                    raise ValueError("malformed input")
        for child in ast.iter_child_nodes(nd):
            check_node(child)

    check_node(node)

    try:
        result = eval(compile(node, '<string>', 'eval'), {"Fraction": Fraction, "__builtins__": {}})
    except ZeroDivisionError:
        raise ValueError("zero denominator")
    except Exception:
        raise ValueError("malformed input")

    if not isinstance(result, Fraction):
        raise ValueError("malformed input")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"
